// Separar productos con stock = 0 y activos con stock
const sinStock = [];
const conStock = [];

for (const item of $input.all()) {
  const product = item.json;

  // Calcular stock total del producto
  let stockTotal = 0;
  const variants = product.variants || [];

  for (const v of variants) {
    if (v.inventory_management === 'shopify') {
      stockTotal += (v.inventory_quantity || 0);
    } else {
      // Sin manejo de inventario = siempre disponible
      stockTotal = 999;
      break;
    }
  }

  const productoInfo = {
    id: product.id,
    titulo: product.title,
    handle: product.handle,
    status: product.status,
    stock: stockTotal,
    // Buscamos el nombre del producto en el título de la campaña de Google Ads
    keywordBusqueda: product.title.split(' ').slice(0, 3).join(' ').toLowerCase()
  };

  if (stockTotal <= 0 && product.status === 'active') {
    sinStock.push({ json: { ...productoInfo, accion: 'PAUSAR_ADS' } });
  } else if (stockTotal > 0) {
    conStock.push({ json: { ...productoInfo, accion: 'ACTIVAR_ADS' } });
  }
}

// Retornar todos los productos con su acción
return [...sinStock, ...conStock];

