const campaignData = $input.first().json;
const productData = $('Clasificar por stock').first().json;

const rows = campaignData[0]?.results || [];

if (rows.length === 0) {
  return [{ json: { mensaje: `No se encontró campaña para: ${productData.titulo}`, accion: 'SIN_CAMPAÑA' } }];
}

const accionesNecesarias = [];

for (const row of rows) {
  const estadoActual = row.campaign.status;
  const accionDeseada = productData.accion;

  // Solo actuar si el estado actual es diferente al deseado
  if (accionDeseada === 'PAUSAR_ADS' && estadoActual === 'ENABLED') {
    accionesNecesarias.push({
      json: {
        campaignId: row.campaign.id,
        campaignName: row.campaign.name,
        producto: productData.titulo,
        stock: productData.stock,
        estadoActual,
        accion: 'PAUSAR',
        nuevoEstado: 'PAUSED'
      }
    });
  } else if (accionDeseada === 'ACTIVAR_ADS' && estadoActual === 'PAUSED') {
    accionesNecesarias.push({
      json: {
        campaignId: row.campaign.id,
        campaignName: row.campaign.name,
        producto: productData.titulo,
        stock: productData.stock,
        estadoActual,
        accion: 'ACTIVAR',
        nuevoEstado: 'ENABLED'
      }
    });
  }
}

return accionesNecesarias.length > 0 ? accionesNecesarias : [{ json: { accion: 'SIN_CAMBIO', campaignName: rows[0].campaign.name } }];
